section.programlisting:
var sheet Drawing(500, 200)
sheet.rect(0, 0, 500, 200, "white")
for i in 10
{
    let x 30 + i * 48
    sheet.circle(x, 100, 6 + i * 2, "#2a5db0")
    sheet.text(x - 5, 180, "`i`", "black")
}
sheet.show()

var curve Chart("A parabola")
curve.axes("x", "x * x")
for i in 41
{
    let x (i as f64) / 10.0 - 2.0
    curve.point(x, x * x)
}
curve.dots()
curve.show()
